export function FileMetadata({
  name = "{{name}}",
  size = "{{size}}",
  modified = "{{modified}}",
  owner = "{{owner}}",
  accent = "{{accent}}",
}) {
  const row = { display: "flex", justifyContent: "space-between", gap: 10, padding: "6px 0", borderBottom: "1px solid #24143012" };
  const label = { color: "#24143099", fontWeight: 600 };
  const value = { margin: 0, textAlign: "right", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", maxWidth: 160 };
  return (
    <dl style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 280, padding: "16px 18px", borderRadius: 10, boxSizing: "border-box", border: "1px solid #24143018", borderTop: `3px solid ${accent}`, margin: 0 }}>
      <div style={row}><dt style={label}>Name</dt><dd style={value}>{name}</dd></div>
      <div style={row}><dt style={label}>Size</dt><dd style={value}>{size}</dd></div>
      <div style={row}><dt style={label}>Modified</dt><dd style={value}><time dateTime="2026-08-14">{modified}</time></dd></div>
      <div style={{ ...row, borderBottom: "none" }}><dt style={label}>Owner</dt><dd style={value}>{owner}</dd></div>
    </dl>
  );
}
